class SegmentTree {
    vector<int> tree;
public:
    SegmentTree(int n) { tree.resize(4 * n); }
    void build(int node, int start, int end, vector<int>& arr) {
        if (start == end) { tree[node] = arr[start]; return; }
        int mid = (start + end) / 2;
        build(2 * node, start, mid, arr);
        build(2 * node + 1, mid + 1, end, arr);
        tree[node] = tree[2 * node] + tree[2 * node + 1];
    }
    int query(int node, int start, int end, int l, int r) {
        if (r < start || end < l) return 0;
        if (l <= start && end <= r) return tree[node];
        int mid = (start + end) / 2;
        return query(2 * node, start, mid, l, r) + query(2 * node + 1, mid + 1, end, l, r);
    }
    void update(int node, int start, int end, int idx, int val) {
        if (start == end) { tree[node] = val; return; }
        int mid = (start + end) / 2;
        if (start <= idx && idx <= mid) update(2 * node, start, mid, idx, val);
        else update(2 * node + 1, mid + 1, end, idx, val);
        tree[node] = tree[2 * node] + tree[2 * node + 1];
    }
};

class LazySegmentTree {
    vector<int> tree, lazy;
public:
    LazySegmentTree(int n) { tree.resize(4 * n); lazy.resize(4 * n, 0); }
    void updateRange(int node, int start, int end, int l, int r, int val) {
        if (lazy[node] != 0) { // Pending updates
            tree[node] += (end - start + 1) * lazy[node];
            if (start != end) { lazy[2*node] += lazy[node]; lazy[2*node+1] += lazy[node]; }
            lazy[node] = 0;
        }
        if (start > end || start > r || end < l) return;
        if (start >= l && end <= r) { // Complete overlap
            tree[node] += (end - start + 1) * val;
            if (start != end) { lazy[2*node] += val; lazy[2*node+1] += val; }
            return;
        }
        int mid = (start + end) / 2; // Partial overlap
        updateRange(2*node, start, mid, l, r, val);
        updateRange(2*node+1, mid+1, end, l, r, val);
        tree[node] = tree[2*node] + tree[2*node+1];
    }
    // Query logic similar to updateRange logic
};
